create extension if not exists pgcrypto;
create extension if not exists btree_gist;
create type public.booking_status as enum ('reserved','checked_in','completed','cancelled');
create type public.payment_status as enum ('unpaid','partial','paid','refunded');
create table public.courts (id uuid primary key default gen_random_uuid(),name text not null unique,court_type text not null default 'Indoor · Reguler',is_active boolean not null default true,created_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(),name text not null,phone text not null,notes text,created_at timestamptz not null default now());
create table public.pricing_rules (id uuid primary key default gen_random_uuid(),name text not null,start_time time not null,end_time time not null,price_per_hour numeric(12,2) not null check(price_per_hour>=0),days_of_week int[] not null default array[0,1,2,3,4,5,6],active boolean not null default true,created_at timestamptz not null default now(),check(start_time<end_time));
create table public.bookings (id uuid primary key default gen_random_uuid(),booking_code text not null unique default ('BC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),customer_id uuid not null references public.customers(id),court_id uuid not null references public.courts(id),starts_at timestamptz not null,ends_at timestamptz not null,duration_minutes int generated always as (extract(epoch from (ends_at-starts_at))/60)::int stored,hourly_rate numeric(12,2) not null,total_amount numeric(12,2) not null,status public.booking_status not null default 'reserved',payment_status public.payment_status not null default 'unpaid',notes text,created_at timestamptz not null default now(),check(ends_at>starts_at),check(total_amount>=0));
alter table public.bookings add constraint no_overlapping_court_bookings exclude using gist(court_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(status<>'cancelled');
create table public.payments (id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,amount numeric(12,2) not null check(amount>0),method text not null default 'cash',reference text,paid_at timestamptz not null default now(),received_by uuid references auth.users(id));
create table public.expenses (id uuid primary key default gen_random_uuid(),category text not null,description text not null,amount numeric(12,2) not null check(amount>0),spent_at date not null default current_date,created_at timestamptz not null default now());
create table public.maintenance (id uuid primary key default gen_random_uuid(),court_id uuid not null references public.courts(id),starts_at timestamptz not null,ends_at timestamptz not null,reason text not null,check(ends_at>starts_at));
create table public.app_settings (key text primary key,value jsonb not null,updated_at timestamptz not null default now());
insert into public.courts(name) values('Lapangan 1'),('Lapangan 2'),('Lapangan 3'),('Lapangan 4'),('Lapangan 5') on conflict do nothing;
insert into public.pricing_rules(name,start_time,end_time,price_per_hour) values('Off peak','07:00','16:00',50000),('Peak','16:00','23:00',65000);
insert into public.app_settings(key,value) values('venue','{"name":"Badminton Center","opening":"07:00","closing":"23:00","base_rate":50000,"deposit_mode":"custom"}'::jsonb) on conflict(key) do nothing;
do $$ declare t text; begin foreach t in array array['courts','customers','pricing_rules','bookings','payments','expenses','maintenance','app_settings'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy "admin full access" on public.%I for all to authenticated using ((auth.jwt()->''app_metadata''->>''role'')=''admin'') with check ((auth.jwt()->''app_metadata''->>''role'')=''admin'')',t);end loop;end $$;
grant usage on schema public to authenticated;
grant select,insert,update,delete on public.courts,public.customers,public.pricing_rules,public.bookings,public.payments,public.expenses,public.maintenance,public.app_settings to authenticated;
